#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int r,c;scanf("%d %d",&r,&c);
vector<string>g(r);
for(int i=0;i<r;++i)cin>>g[i];
queue<pair<int,int>>q;
for(int i=0;i<r;++i)for(int j:{0,c-1})
if(g[i][j]=='O'){g[i][j]='#';q.push({i,j});}
for(int j=0;j<c;++j)for(int i:{0,r-1})
if(g[i][j]=='O'){g[i][j]='#';q.push({i,j});}
int dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};
while(!q.empty()){auto pr=q.front();q.pop();
for(int d=0;d<4;++d){int nx=pr.first+dx[d],ny=pr.second+dy[d];
if(nx<0||nx>=r||ny<0||ny>=c)continue;
if(g[nx][ny]=='O'){g[nx][ny]='#';q.push({nx,ny});}}}
for(int i=0;i<r;++i){for(int j=0;j<c;++j)
printf("%c",g[i][j]=='#'?'O':'X');printf("\n");}
return 0;}

